class Solution {
  public int minimumPairRemoval(int[] nums) {
    int n = nums.length;
    long[] val = new long[n];
    int[] prev = new int[n], next = new int[n];
    boolean[] alive = new boolean[n];
    int bad = 0;
    java.util.PriorityQueue<long[]> pq =
        new java.util.PriorityQueue<>(
            (a, b) -> a[0] != b[0] ? Long.compare(a[0], b[0]) : Long.compare(a[1], b[1]));
    for (int i = 0; i < n; i++) {
      val[i] = nums[i];
      prev[i] = i - 1;
      next[i] = i + 1 < n ? i + 1 : -1;
      alive[i] = true;
      if (i + 1 < n) {
        pq.add(new long[] {val[i] + nums[i + 1], i, i + 1});
        if (nums[i] > nums[i + 1]) bad++;
      }
    }
    int ops = 0;
    while (bad > 0) {
      long[] top = pq.poll();
      int i = (int) top[1], j = (int) top[2];
      if (!alive[i] || !alive[j] || next[i] != j || val[i] + val[j] != top[0]) continue;
      int p = prev[i], q = next[j];
      if (p >= 0 && val[p] > val[i]) bad--;
      if (val[i] > val[j]) bad--;
      if (q >= 0 && val[j] > val[q]) bad--;
      val[i] += val[j];
      alive[j] = false;
      next[i] = q;
      if (q >= 0) prev[q] = i;
      if (p >= 0 && val[p] > val[i]) bad++;
      if (q >= 0 && val[i] > val[q]) bad++;
      if (p >= 0) pq.add(new long[] {val[p] + val[i], p, i});
      if (q >= 0) pq.add(new long[] {val[i] + val[q], i, q});
      ops++;
    }
    return ops;
  }
}
